var e=[{id:"caja",n:1,title:"Caja de control e IA",icon:"developer_board",text:"El cerebro del nodo: un ESP32 controla las luces a 110 V, un switch PoE industrial alimenta las c\xE1maras y una caja de IA sin ventilador analiza el video en el propio poste.",note:"Sensores de puerta y vibraci\xF3n avisan a la central si alguien abre el gabinete."},{id:"bateria",n:2,title:"Respaldo LiFePO4",icon:"battery_charging_full",text:"Banco de litio-ferrofosfato de \u2248 1,3 kWh: sem\xE1foro, c\xE1maras e IA siguen activos hasta 5 horas durante un corte de Corpoelec.",note:"4.000\u20136.000 ciclos de descarga profunda: 8 a 10 a\xF1os de vida \xFAtil."},{id:"valla",n:3,title:"Valla LED publicitaria",icon:"featured_video",text:"Pantalla exterior de alto brillo con c\xF3digo QR para comprar pauta. Sus ingresos financian el mantenimiento del nodo.",note:"En apag\xF3n se apaga sola para no consumir la bater\xEDa."},{id:"ptz",n:4,title:"C\xE1mara domo PTZ",icon:"videocam",text:"Domo de 8 MP con zoom \xF3ptico 36\xD7. Cuando la IA detecta un evento, gira y enfoca el punto autom\xE1ticamente para que el operador confirme.",note:"Tecnolog\xEDa de baja luz para operar de noche y en apagones."},{id:"balas",n:5,title:"C\xE1maras fijas tipo bala",icon:"photo_camera",text:"Dos c\xE1maras fijas vigilan los accesos de la intersecci\xF3n: lectura de placas (ANPR), conteo vehicular y detecci\xF3n de novedades viales.",note:"Resistentes a la intemperie (IP66) y al vandalismo (IK10)."},{id:"semaforo",n:6,title:"Sem\xE1foro ECO LED",icon:"traffic",text:"Cabezales LED que consumen m\xE1s de 80 % menos que los sem\xE1foros tradicionales. Su estado se replica en tiempo real en el Mapa Vivo.",note:"Preparado para ciclos adaptativos y \u201Cola verde\u201D para ambulancias (fase 7)."},{id:"mic",n:7,title:"Micr\xF3fono de eventos",icon:"graphic_eq",text:"Clasifica sonidos (grito, disparo, vidrio roto, choque) en un b\xFAfer de 2 segundos en memoria. Nunca graba ni transmite audio.",note:"Solo sale del poste una etiqueta: \u201Cgrito \xB7 0,86 \xB7 DSIP-04\u201D."},{id:"antena",n:8,title:"Enlace P2P y 4G",icon:"cell_tower",text:"Radioenlace de 5 GHz o fibra hacia la central, con m\xF3dem 4G multioperador de respaldo. Solo env\xEDa eventos de pocos KB.",note:"Si el enlace cae, el nodo guarda los eventos y los sincroniza al volver."},{id:"poste",n:9,title:"Poste en L galvanizado",icon:"architecture",text:"Estructura de acero galvanizado con base de concreto, dise\xF1ada para soportar la valla y vientos fuertes.",note:"Canalizaci\xF3n interna para proteger el cableado del robo."}],a={ptz:{title:"Domo PTZ DarkFighter 8 MP",image:"images/ptz.webp",items:[["photo_camera",'Sensor CMOS 1/1.8"',"Escaneo progresivo para capturas n\xEDtidas y detalladas."],["zoom_in","Zoom \xF3ptico 36\xD7","M\xE1s 16\xD7 digital para acercarse a detalles en \xE1reas extensas."],["brightness_medium","DarkFighter 2.0","Excelente rendimiento con muy poca luz."],["filter_hdr","AWDR de 140 dB","Imagen clara aun con fuerte contraluz."],["center_focus_strong","Enfoque r\xE1pido","Autoenfoque de alta precisi\xF3n al girar hacia una alerta."],["screen_rotation","Giroscopio","Imagen estable con viento o vibraci\xF3n del poste."],["shield","IP67 \xB7 IK10","Resistente al agua, al polvo y al vandalismo."],["water","NEMA 4X (opcional)","Resistencia a la corrosi\xF3n en ambientes hostiles."]]},camera:{title:"C\xE1mara de videoanal\xEDtica Ultra HD",image:"images/8.webp",items:[["hd","Ultra HD","M\xE1ximo detalle para lectura de placas y conteo."],["filter_hdr","Procesador de imagen con IA","Reducci\xF3n de ruido para im\xE1genes limpias de noche."],["light_mode","Luz h\xEDbrida inteligente","Infrarrojo, luz blanca o h\xEDbrida seg\xFAn la escena."],["brightness_medium","WDR de 130 dB","Nitidez con contraluz fuerte."],["mic","Entrada de audio","Permite detectar excepciones de audio (Nivel 0 de IA)."],["notification_important","Puertos de alarma","Integraci\xF3n con sensores perimetrales."],["shield","IP66 \xB7 IK10","Resistencia a intemperie y vandalismo."]]},semaforo:{title:"Sem\xE1foro inteligente ECO LED",image:"images/semaforo.webp",items:[["eco","\u221280 % de consumo","Frente a sem\xE1foros incandescentes o hal\xF3genos."],["traffic","Estado en tiempo real","Cada cambio de luz se refleja en el Mapa Vivo."],["directions_walk","Cruce peatonal","Preparado para extender el tiempo a personas mayores."],["emergency","Prioridad de emergencia","Ola verde para ambulancias y bomberos (fase 7)."],["battery_charging_full","Sigue en apag\xF3n","Alimentado por el banco LiFePO4 del nodo."],["psychology","Ciclos adaptativos","Ajuste seg\xFAn el conteo vehicular de las c\xE1maras."]]},pantalla:{title:"Valla LED exterior",image:"images/pantalla.webp",items:[["hd","Pixel pitch fino","Legible a plena luz del sol."],["light_mode","Brillo adaptativo","Sensores ajustan los nits de d\xEDa y de noche."],["thermostat","Chasis IP65","Herm\xE9tico al polvo y al agua, apto para el calor de los llanos."],["qr_code_2","Pauta por QR","El anunciante compra y sube su contenido desde el tel\xE9fono."],["campaign","Mensajes de servicio","Rutas alternas, alertas de crecidas y avisos de Protecci\xF3n Civil."],["power_off","Modo apag\xF3n","Se apaga sola para proteger la bater\xEDa del nodo."]]},edge:{title:"Caja IA en el poste (Panoptes Vital)",image:null,icon:"memory",items:[["memory","C\xF3mputo de IA industrial","Clase Jetson Orin NX 16 GB o RK3588 + Hailo-8."],["thermostat","Sin ventilador","Opera de \u221220 a 70 \xB0C dentro del gabinete al sol."],["bolt","\u2248 15 W de consumo","Baja a 2\u20135 cuadros por segundo en apag\xF3n."],["cloud_off","Funciona sin internet","Procesa localmente y guarda eventos si cae el enlace."],["mic_off","Audio sin grabaci\xF3n","Clasifica y descarta; nunca almacena conversaciones."],["sync","Actualizable","Nuevos modelos se instalan de forma remota y firmada."]]},antena:{title:"Enlace Ubiquiti P2P",image:"images/antena.webp",items:[["settings_input_antenna","5,1\u20135,8 GHz","Espectro optimizado para evitar interferencias."],["signal_cellular_alt","Alta ganancia","Enlaces estables de largo alcance hacia la central."],["settings_ethernet","MIMO 2\xD72","Doble polarizaci\xF3n para velocidad y robustez."],["air","Resistente al viento","Mantiene la alineaci\xF3n con cargas de viento elevadas."]]},cpu:{title:"Servidor de procesamiento",image:"images/cpu.webp",items:[["developer_board","Xeon multin\xFAcleo","Decodificaci\xF3n de m\xFAltiples flujos de video."],["memory","128 GB RAM ECC","Estabilidad para operaci\xF3n 24/7."],["storage","NVMe","Lectura y escritura inmediata de eventos y capturas ANPR."],["smart_toy","GPU de inferencia","Para IA sobre c\xE1maras comerciales se recomienda el servidor GPU del addon."],["power","Fuente redundante","Operaci\xF3n ininterrumpida del hardware."]]},videowall:{title:"Video wall de control",image:"images/videowall.webp",items:[["grid_view","Sin bisel","LED Fine Pitch COB P1.5: imagen continua, sin cortes."],["brightness_high","1.000 nits HDR","Visibilidad perfecta en la sala de control."],["schedule","Operaci\xF3n 24/7","Dise\xF1ado para misi\xF3n cr\xEDtica."],["developer_board","Procesador Novastar","Ventanas, zonas ampliadas y ruteo flexible de c\xE1maras."]]}},o=[{title:"Video wall de monitoreo",icon:"monitor",x:42,y:32,text:"Pantalla LED Fine Pitch P1.5 sin bisel, 1.000 nits, para operaci\xF3n 24/7. Muestra el Mapa Vivo y las alertas priorizadas, no un mosaico de c\xE1maras aburridas.",note:"Ergonom\xEDa: consolas dise\xF1adas para reducir la fatiga visual."},{title:"Servidores y c\xF3mputo",icon:"dns",x:64,y:72,text:"Rack cerrado de 42U con procesamiento local de video, base de datos de eventos y el motor Panoptes Core. Con el addon, suma un servidor GPU para la IA de la central.",note:"Switches capa 3 y firewall protegen la red municipal."},{title:"Acceso y climatizaci\xF3n",icon:"fingerprint",x:74,y:35,text:"Climatizaci\xF3n redundante que mantiene el rack entre 18 y 21 \xB0C, sensores de humedad e inundaci\xF3n y puerta reforzada con acceso biom\xE9trico.",note:"Solo personal autorizado entra a la sala."},{title:"Estaciones de operadores",icon:"desktop_windows",x:22,y:70,text:"Puestos con GPU dedicada para mapas y video. El operador valida cada alerta con el video en vivo y despacha en un clic.",note:"Cuentas nominales: cada acci\xF3n queda en la bit\xE1cora inmutable."},{title:"Conexi\xF3n con los nodos",icon:"settings_input_antenna",x:92,y:45,text:"Fibra o radioenlaces P2P traen los eventos y el video bajo demanda desde los nodos DSIP. Si un enlace cae, los nodos sincronizan al reconectarse.",note:"Respaldo 4G multioperador para los nodos cr\xEDticos."}],i=[{img:"images/semaforoiot.webp",title:"Sem\xE1foros IoT en tiempo real",text:"Cada intersecci\xF3n controlada por un nodo ESP32 se replica en el mapa: si el sem\xE1foro cambia a rojo en la calle, cambia a rojo en la pantalla central."},{img:"images/respaldo.webp",title:"Respaldo el\xE9ctrico LiFePO4",text:"Las bater\xEDas de litio mantienen sem\xE1foros y c\xE1maras funcionando durante los apagones y avisan a la central el estado de carga."},{img:"images/central.webp",title:"Sala de operaciones C3I",text:"Todos los flujos del municipio en una sola sala: mapa, alertas priorizadas y despacho en un clic."},{img:"images/busquedaplaca.webp",title:"Lectura de placas (ANPR)",text:"Dos etapas de IA: primero localiza la placa y luego lee los caracteres. Resiste cambios de velocidad, iluminaci\xF3n y sombras. Las consultas a bases de veh\xEDculos solicitados requieren convenio."},{img:"images/busquedanocturna.webp",title:"ANPR nocturno",text:"La lectura de placas funciona de noche y durante apagones gracias a la iluminaci\xF3n infrarroja y al respaldo del nodo."},{img:"images/busquedarostro.webp",title:"B\xFAsqueda biom\xE9trica (con orden)",text:"Comparaci\xF3n facial solo ante una orden de autoridad competente y con convenio para acceder a bases oficiales. Nunca en reuniones p\xFAblicas ni en entornos escolares; siempre con verificaci\xF3n humana y registro en bit\xE1cora."}],n=[{code:"IA-01",icon:"personal_injury",title:"Persona ca\xEDda o desmayada",what:"Persona que cae y queda inm\xF3vil en el suelo m\xE1s de 45\u201390 segundos.",ve:"Golpes de calor, pensionados en colas de bancos, motorizado ca\xEDdo de noche, entrada del hospital.",filter:"Personas sentadas en el brocal, mec\xE1nicos bajo un carro (zonas de exclusi\xF3n) y personas en situaci\xF3n de calle, que se derivan a servicios sociales."},{code:"IA-02",icon:"car_crash",title:"Novedades viales",what:"Choques, moto ca\xEDda, veh\xEDculo detenido en la intersecci\xF3n, contrasentido y peat\xF3n en la calzada.",ve:"Accidentes de motorizados e intersecciones sin sem\xE1foro durante los apagones.",filter:"Doble fila en horario de carga y descarga, seg\xFAn reglas por zona."},{code:"IA-03",icon:"local_fire_department",title:"Humo e incendio",what:"Humo y llamas en la v\xEDa, terrenos bald\xEDos y vegetaci\xF3n.",ve:"Quemas de vegetaci\xF3n en temporada seca y de ca\xF1averales en zonas agr\xEDcolas.",filter:"Parrillas de ventas de comida, quema menor de basura, polvo, neblina y escapes di\xE9sel: exige humo persistente y creciente."},{code:"IA-04",icon:"shield_lock",title:"Anti-sabotaje del nodo",what:"C\xE1mara tapada, girada o desenfocada; gabinete abierto; vibraci\xF3n o escalada del poste; bater\xEDa desconectada.",ve:"Robo de bater\xEDas y cable: protege directamente la inversi\xF3n.",filter:"Telara\xF1as e insectos frente al infrarrojo, lluvia fuerte en el lente y p\xE1jaros."},{code:"IA-05",icon:"graphic_eq",title:"Gritos, disparos y vidrios",what:"Gritos de auxilio, detonaciones, rotura de vidrios, impactos y frenazos.",ve:"Robos a mano armada y ri\xF1as nocturnas cerca de licorer\xEDas.",filter:"Cohetones y fuegos artificiales (diciembre, fiestas patronales, b\xE9isbol), escapes de moto, cornetas y recreos escolares. Nunca graba audio."},{code:"IA-06",icon:"groups",title:"Aglomeraciones y multitudes",what:"Densidad de personas, flujo, estampidas, colas y aforo excedido.",ve:"Peregrinaciones y fiestas patronales, ferias, salidas de colegios, terminal y colas en bancos o estaciones de servicio.",filter:"Solo datos agregados: prohibido identificar a los asistentes de reuniones o manifestaciones."}],t=[{code:"IA-07",icon:"edit_note",title:"Copiloto del operador",text:"Redacta el parte de novedades de cada turno y permite buscar en lenguaje natural: \u201Cmoto roja cerca de la farmacia entre 8 y 9 p. m.\u201D. LLM local, sin nube."},{code:"IA-08",icon:"low_priority",title:"Motor de prioridad",text:"Combina video, audio, botones SOS y reportes ciudadanos, ordena por gravedad y mide las falsas alarmas de cada nodo para evitar la fatiga del operador."},{code:"IA-09",icon:"chat",title:"WhatsApp con notas de voz",text:"El ciudadano reporta por texto o nota de voz; la IA transcribe localmente, clasifica, ubica y crea un pin con la c\xE1mara m\xE1s cercana."},{code:"IA-10",icon:"construction",title:"Ciudad mantenida",text:"Detecta huecos, botes de aguas blancas o negras, basura acumulada y alumbrado apagado, y env\xEDa un reporte semanal a la alcald\xEDa."},{code:"IA-11",icon:"power_off",title:"Mapa de apagones",text:"Cada nodo registra cu\xE1ndo se fue la luz y cu\xE1nto dur\xF3: un mapa por sector para planificar y gestionar con Corpoelec con datos reales."},{code:"IA-12",icon:"emergency",title:"Ola verde para ambulancias",text:"Reconoce la sirena y el veh\xEDculo de emergencia y abre los sem\xE1foros de su ruta hacia el hospital."},{code:"IA-13",icon:"pets",title:"Animales en la v\xEDa",text:"Ganado y caballos sueltos en troncales y accesos de noche: alerta a la central y aviso en la valla LED para los conductores."},{code:"IA-14",icon:"person_search",title:"B\xFAsqueda humanitaria",text:"Ni\xF1o o adulto mayor extraviado en una feria o procesi\xF3n: b\xFAsqueda por ropa y colores, sin biometr\xEDa y solo con denuncia formal."},{code:"IA-15",icon:"battery_alert",title:"Mantenimiento predictivo",text:"Vigila la salud de bater\xEDas, c\xE1maras y enlaces para cambiar piezas antes de que un nodo se apague."},{code:"IA-16",icon:"flood",title:"Calles inundadas",text:"Complementa los pluvi\xF3metros: detecta calles anegadas y cauces desbordados en la temporada de lluvias."}],s={start:-3,end:36,phases:[{id:0,kind:"base",name:"Validaci\xF3n y nodo demostrativo",short:"Validaci\xF3n",from:-3,to:0,when:"Antes del contrato (3 meses)",goal:"Demostrar resultados en la calle antes de comprometer la inversi\xF3n completa.",items:["Levantamiento t\xE9cnico sin compromiso","1 nodo DSIP demostrativo durante 90 d\xEDas con IA de nivel 0\u20131","Borrador de ordenanza con anexo de IA responsable","Mesa t\xE9cnica con cuerpos de seguridad y Protecci\xF3n Civil"],cost:"\u2248 $24.639,65 (1 nodo, descontable del piloto)",exit:"Al menos 1 caso de respuesta asistida por IA documentado y \u2265 95 % de disponibilidad del nodo en apagones."},{id:1,kind:"base",name:"Central C3I",short:"Central C3I",from:1,to:2,when:"Meses 1\u20132",goal:"Tener la sala de operaciones lista para recibir los nodos.",items:["Adecuaci\xF3n f\xEDsica y el\xE9ctrica de la sala","Servidores, video wall, UPS y planta el\xE9ctrica","Instalaci\xF3n del n\xFAcleo Panoptes Core","Inicio de la capacitaci\xF3n de operadores"],cost:"$81.709,55 (+ planta el\xE9ctrica recomendada)",exit:"Sala operativa 24/7 con operadores en formaci\xF3n."},{id:2,kind:"base",name:"10 nodos DSIP",short:"Nodos DSIP",from:3,to:5,when:"Meses 3\u20135",goal:"Encender la red de calle.",items:["Izado de postes y montaje de vallas LED","C\xE1maras PTZ y bala con ANPR","Sem\xE1foros ECO LED y bater\xEDas LiFePO4","Enlaces P2P o fibra hacia la central"],cost:"$246.396,50",exit:"10/10 nodos en l\xEDnea y autonom\xEDa en apag\xF3n verificada (\u2265 4 h)."},{id:3,kind:"base",name:"Fusi\xF3n comercial",short:"Fusi\xF3n comercial",from:6,to:8,when:"Meses 6\u20138",goal:"Densificar el mapa con las c\xE1maras que ya existen.",items:["Adhesi\xF3n incentivada (descuento en la patente) de licorer\xEDas, farmacias y comercios","Integraci\xF3n de colegios, liceos y el hospital","Convenios de cifrado y acceso con cada afiliado"],cost:"Sin compra de c\xE1maras; solo integraci\xF3n",exit:"\u2265 60 c\xE1maras comerciales integradas al Mapa Vivo."},{id:4,kind:"base",name:"Operaci\xF3n y concesi\xF3n",short:"Operaci\xF3n",from:9,to:36,when:"Mes 9 en adelante (contrato a 15 a\xF1os)",goal:"Operar, mantener y autofinanciar el sistema.",items:["Comercializaci\xF3n de la pauta en las vallas","Contrato de mantenimiento a 15 a\xF1os","Integraci\xF3n con VEN 911 y 0-800-EXTORSI\xD3N (sujeta a convenio)","Informe p\xFAblico mensual de resultados"],cost:"V\xEDa A: $0 de operaci\xF3n \xB7 V\xEDa B: tarifa fija mensual",exit:"Ocupaci\xF3n publicitaria \u2265 40 % y disponibilidad del sistema \u2265 99 %."},{id:5,kind:"ia",name:"Panoptes Vital IA",short:"IA Vital",from:4,to:12,when:"Meses 4\u201312 (en paralelo)",goal:"Sumar IA local que detecta emergencias sin depender de internet.",items:["Meses 4\u20136: desarrollo del MVP y dataset local","Meses 6\u20139: IA en el poste (ca\xEDdas, novedades, sabotaje, multitudes)","Meses 9\u201312: GPU en la central, copiloto y c\xE1maras comerciales","Audio: al aprobarse el anexo de la ordenanza"],cost:"\u2248 $105.820 (primer despliegue)",exit:"Precisi\xF3n operativa \u2265 60 % a 90 d\xEDas y menos de 5 falsas alarmas por nodo al d\xEDa."},{id:6,kind:"exp",name:"Ciudadan\xEDa y protecci\xF3n civil",short:"Ciudadan\xEDa",from:12,to:18,when:"Meses 12\u201318",goal:"Abrir el sistema al ciudadano y a la protecci\xF3n civil.",items:["WhatsApp ciudadano con notas de voz (IA-09)","Puntos SOS con audio bidireccional en los postes","Alerta temprana hidrometeorol\xF3gica y calles inundadas","Mapa de apagones (IA-11) y ciudad mantenida (IA-10)"],cost:"\u2248 $40.000\u201360.000 seg\xFAn m\xF3dulos",exit:"Tiempo de atenci\xF3n a reportes ciudadanos menor a 10 minutos."},{id:7,kind:"exp",name:"Ciudad inteligente y expansi\xF3n",short:"Expansi\xF3n",from:18,to:36,when:"Meses 18\u201336",goal:"Pasar de la seguridad a la gesti\xF3n urbana y replicar el modelo.",items:["Semaforizaci\xF3n adaptativa y ola verde para ambulancias","Dron de primera respuesta","Enlace satelital de respaldo (sujeto a habilitaci\xF3n)","Animales en la v\xEDa en troncales y l\xEDnea agroindustrial","R\xE9plica en otros municipios"],cost:"Por m\xF3dulo (p. ej., dron \u2248 $25.000\u201340.000)",exit:"R\xE9plica en al menos un municipio adicional."}]};export{e as a,a as b,o as c,i as d,n as e,t as f,s as g};
